import type { RuleSystem } from '../../src/engine/api';
// Synthetic fixtures: no product rules, story, artwork or imports from src/games.
export function registerTestRules(rules: RuleSystem) {
  rules.registerCondition('allCollected', ({ level, collected }) =>
    (level.entities ?? [])
      .filter((e) => e.type === 'collectible')
      .every((e) => collected.includes(e.id)),
  );
}
